function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'NumArray' || !Array.isArray(args[0]) || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Start with NumArray and one array nums.';
  const nums = args[0][0];
  if (nums.length < 1 || nums.length > 30000) return 'nums needs 1 to 30000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < -100 || v > 100)) return 'Each value in nums is a whole number from -100 to 100.';
  if (operations.length - 1 > 30000) return 'At most 30000 calls to update and sumRange.';
  const n = nums.length;
  for (let i = 1; i < operations.length; i++) {
    const [a, b] = args[i];
    if (args[i].length !== 2 || !Number.isInteger(a) || !Number.isInteger(b)) return 'Each call takes two whole numbers.';
    if (operations[i] === 'update') {
      if (a < 0 || a >= n) return 'update needs 0 <= index < nums.length.';
      if (b < -100 || b > 100) return 'update needs val from -100 to 100.';
    } else if (operations[i] === 'sumRange') {
      if (a < 0 || a > b || b >= n) return 'sumRange needs 0 <= left <= right < nums.length.';
    } else return 'Only update and sumRange can follow the constructor.';
  }
  return null;
}

