class NumArray {
  constructor(nums) {
    this.n = nums.length;
    this.tree = new Array(2 * this.n).fill(0);
    for (let i = 0; i < this.n; i++) {
      this.tree[this.n + i] = nums[i];
    }
    for (let node = this.n - 1; node > 0; node--) {
      this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
    }
  }

  update(index, val) {
    let node = index + this.n;
    this.tree[node] = val;
    while (node > 1) {
      node = Math.floor(node / 2);
      this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
    }
  }

  sumRange(left, right) {
    let low = left + this.n;
    let high = right + this.n + 1;
    let sum = 0;
    while (low < high) {
      if (low % 2 === 1) {
        sum += this.tree[low];
        low++;
      }
      if (high % 2 === 1) {
        high--;
        sum += this.tree[high];
      }
      low = Math.floor(low / 2);
      high = Math.floor(high / 2);
    }
    return sum;
  }
}

