function generate(rand, size) {
  const n = size === 'large' ? 2000 : 1 + Math.floor(rand() * 8);
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 12);
  const span = size === 'large' || rand() < 0.5 ? 100 : 3;
  const value = () => Math.floor(rand() * (2 * span + 1)) - span;
  const nums = Array.from({ length: n }, value);
  const operations = ['NumArray'];
  const args = [[nums]];
  const updateRate = 0.2 + rand() * 0.6;
  for (let i = 0; i < calls; i++) {
    if (rand() < updateRate) {
      operations.push('update');
      args.push([Math.floor(rand() * n), value()]);
    } else {
      const a = Math.floor(rand() * n);
      const b = Math.floor(rand() * n);
      operations.push('sumRange');
      args.push([Math.min(a, b), Math.max(a, b)]);
    }
  }
  return [operations, args];
}
